import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 200;
    static final int MAXM = 100000;
    static final int INF = 99999999;

    static int[][] grid = new int[20][20];
    static int[][] adj = new int[MAXN][MAXN];
    static int n, totalNodes, t;
    static String line;
    static int[][] startPoints = new int[MAXN][3], endPoints = new int[MAXN][3];
    static int zr, zc;
    static int cX, cY;
    static int[][] dir = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

    static int[] distances = new int[MAXN];
    static int[] q = new int[MAXM];

    static class Edge {
        int from, to, cap, next;
        public Edge(int from, int to, int cap, int next) {
            this.from = from;
            this.to = to;
            this.cap = cap;
            this.next = next;
        }
    }

    static ArrayList<Edge> flowEdges = new ArrayList<>();
    static int[] head = new int[MAXN];
    static int edgeIdx;
    static int sNode, tNode;

    static int[] level = new int[MAXN];
    static int[] ptr = new int[MAXN];

    static int[] hu = new int[MAXN][3];
    static int[] re = new int[MAXN][3];

    static int indexOf(int r, int c) {
        if (r > 0 && r <= n && c > 0 && c <= n && grid[r][c] != -1)
            return (r - 1) * n + c;
        return -1;
    }

    static void createGraph() {
        totalNodes = n * n;
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(adj[i], -1);
        }
        for (int r1 = 1; r1 <= n; r1++) {
            for (int c1 = 1; c1 <= n; c1++) {
                if (grid[r1][c1] == -1) continue;
                int p1 = (r1 - 1) * n + c1;
                adj[p1][p1] = 0;
                for (int i = 0; i < 4; i++) {
                    int r2 = r1 + dir[i][0];
                    int c2 = c1 + dir[i][1];
                    if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && grid[r2][c2] != -1) {
                        int p2 = (r2 - 1) * n + c2;
                        adj[p1][p2] = 1;
                    }
                }
            }
        }
    }

    static void computeDistances() {
        int front = 0, rear = 1;
        Arrays.fill(distances, INF);
        int s = (zr - 1) * n + zc;
        distances[s] = 0;
        q[0] = s;
        while (front < rear) {
            int u = q[front++];
            for (int v = 1; v <= totalNodes; v++) {
                if (adj[u][v] == 1 && distances[v] > distances[u] + 1) {
                    distances[v] = distances[u] + 1;
                    q[rear++] = v;
                }
            }
        }
    }

    static void floydAllPairs() {
        for (int k = 1; k <= totalNodes; k++) {
            for (int i = 1; i <= totalNodes; i++) {
                for (int j = 1; j <= totalNodes; j++) {
                    if (adj[i][k] != -1 && adj[k][j] != -1) {
                        if (adj[i][j] == -1 || adj[i][j] > adj[i][k] + adj[k][j]) {
                            adj[i][j] = adj[i][k] + adj[k][j];
                        }
                    }
                }
            }
        }
    }

    static void addFlowEdge(int u, int v, int cap) {
        flowEdges.add(new Edge(u, v, cap, head[u]));
        head[u] = flowEdges.size() - 1;
        flowEdges.add(new Edge(v, u, 0, head[v]));
        head[v] = flowEdges.size() - 1;
    }

    static boolean buildLevelGraph() {
        Arrays.fill(level, -1);
        level[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int i = head[u]; i != -1; i = flowEdges.get(i).next) {
                int v = flowEdges.get(i).to;
                if (flowEdges.get(i).cap > 0 && level[v] == -1) {
                    level[v] = level[u] + 1;
                    q.offer(v);
                }
            }
        }
        return level[tNode] != -1;
    }

    static int sendFlow(int u, int flow) {
        if (u == tNode) return flow;
        for (int i = ptr[u]; i != -1; i = flowEdges.get(i).next) {
            int v = flowEdges.get(i).to;
            if (flowEdges.get(i).cap > 0 && level[v] == level[u] + 1) {
                int pushed = sendFlow(v, Math.min(flow, flowEdges.get(i).cap));
                if (pushed > 0) {
                    flowEdges.get(i).cap -= pushed;
                    flowEdges.get(i ^ 1).cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i <= totalNodes + 1; i++) ptr[i] = head[i];
            int pushed;
            while ((pushed = sendFlow(sNode, INF)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static int solve() {
        grid[zr][zc] = 0;
        createGraph();
        computeDistances();
        grid[zr][zc] = -1;
        createGraph();
        floydAllPairs();
        flowEdges.clear();
        Arrays.fill(head, -1);
        edgeIdx = 0;
        sNode = 0;
        tNode = cX + cY + 1;
        for (int i = 1; i <= cX; i++) {
            addFlowEdge(sNode, i, hu[i][2]);
        }
        for (int i = 1; i <= cY; i++) {
            addFlowEdge(cX + i, tNode, re[i][2]);
        }
        int p = (zr - 1) * n + zc;
        for (int i = 1; i <= cX; i++) {
            for (int j = 1; j <= cY; j++) {
                int p1 = (hu[i][0] - 1) * n + hu[i][1];
                int p2 = (re[j][0] - 1) * n + re[j][1];
                if (adj[p1][p2] != -1 && adj[p1][p2] <= t && adj[p1][p2] < distances[p2]) {
                    addFlowEdge(i, cX + j, INF);
                } else if (adj[p1][p2] != -1 && adj[p1][p2] <= t && adj[p1][p2] == distances[p2]) {
                    for (int z = 0; z < 4; z++) {
                        int rr = re[j][0] + dir[z][0];
                        int cc = re[j][1] + dir[z][1];
                        int pp = indexOf(rr, cc);
                        if (pp != -1) {
                            if (adj[p1][pp] == adj[p1][p2] - 1 && adj[p1][pp] < distances[pp]) {
                                addFlowEdge(i, cX + j, INF);
                            }
                        }
                    }
                }
            }
        }
        return maxFlow();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        cX = 0;
        cY = 0;
        for (int i = 0; i < 20; i++) {
            Arrays.fill(grid[i], 0);
        }
        for (int i = 1; i <= n; i++) {
            line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch == 'Y') {
                    grid[i][j + 1] = -1;
                } else if (ch == 'Z') {
                    zr = i;
                    zc = j + 1;
                    grid[i][j + 1] = -1;
                } else if (ch > '0' && ch <= '9') {
                    cX++;
                    hu[cX][0] = i;
                    hu[cX][1] = j + 1;
                    hu[cX][2] = ch - '0';
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch > '0' && ch <= '9') {
                    cY++;
                    re[cY][0] = i;
                    re[cY][1] = j + 1;
                    re[cY][2] = ch - '0';
                }
            }
        }
        System.out.println(solve());
    }
}
